<script lang="ts">
	import type { PptxSlide } from 'pptx-viewer-core'; import type { CanvasSize } from 'pptx-viewer-shared'; import { useTranslator } from '../../i18n/context'; import SlideStage from './SlideStage.svelte';

	const { slides, canvasSize, mediaDataUrls, current, onselect, onmove, onclose }: { slides: PptxSlide[]; canvasSize: CanvasSize; mediaDataUrls: Map<string,string>; current: number; onselect: (index:number)=>void; onmove:(from:number,to:number)=>void; onclose:()=>void } = $props(); const t=useTranslator(); const scale=$derived(180/canvasSize.width);
</script>
<div class="overlay"><header><h2>{t('pptx.view.slideSorter')}</h2><button onclick={onclose}>×</button></header><main>{#each slides as slide,index}<article class:active={current===index}><button class="preview" onclick={() => { onselect(index); onclose(); }}><SlideStage {slide} {canvasSize} {mediaDataUrls} {scale} presenting={false} /></button><footer><span>{index+1}</span><button disabled={index===0} onclick={() => onmove(index,index-1)}>←</button><button disabled={index===slides.length-1} onclick={() => onmove(index,index+1)}>→</button></footer></article>{/each}</main></div>
<style>.overlay{position:absolute;inset:0;z-index:70;overflow:auto;background:var(--pptx-background,#11111b)}header{position:sticky;z-index:2;top:0;display:flex;align-items:center;justify-content:space-between;padding:12px 18px;border-bottom:1px solid var(--pptx-border,#3f3f52);background:var(--pptx-card,#1e1e2e)}h2{margin:0;font-size:14px}header button{border:0;background:transparent;color:inherit;font-size:20px}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:18px;padding:24px}article{display:grid;justify-content:center;gap:6px;padding:9px;border:2px solid transparent;border-radius:8px;background:var(--pptx-card,#1e1e2e)}article.active{border-color:var(--pptx-primary,#c43b32)}.preview{width:180px;height:calc(180px * 9 / 16);overflow:hidden;border:0;padding:0;background:#fff;text-align:left}article footer{display:flex;align-items:center;gap:5px;font-size:11px}article footer span{flex:1}article footer button{border:1px solid var(--pptx-border,#3f3f52);border-radius:4px;background:var(--pptx-muted,#2a2a3d);color:inherit}</style>
